    private static (string, string) Restoration() => (
        "Hold still to restore {shared.restoration_heal}, {AbilityRestoration.StaminaRestoredPerSecond|pct} stamina, {AbilityRestoration.EitrRestoredPerSecond|pct} eitr and {AbilityRestoration.EnergyRestoredPerSecond} energy each second; Rested after {AbilityRestoration.TicksBeforeRested|s}. Hits interrupt it. After {=10|s}, all remaining energy is consumed in a lightning blast within {AbilityRestoration.EnergyBlastRadius|m}: base {shared.restoration_blast} damage, increased by {AbilityRestoration.EnergyBlastBonusDamagePerPoint|pct} per energy point consumed. The displayed base excludes this variable energy bonus.",
        "Неподвижно восстанавливает {shared.restoration_heal}, {AbilityRestoration.StaminaRestoredPerSecond|pct} выносливости, {AbilityRestoration.EitrRestoredPerSecond|pct} эйтра и {AbilityRestoration.EnergyRestoredPerSecond} энергии в секунду. Отдых через {AbilityRestoration.TicksBeforeRested|s}. Попадания прерывают эффект. Через {=10|s} оставшаяся энергия расходуется на взрыв молнии в радиусе {AbilityRestoration.EnergyBlastRadius|m}: база {shared.restoration_blast} урона, плюс {AbilityRestoration.EnergyBlastBonusDamagePerPoint|pct} за каждую потраченную единицу энергии. Показанная база не включает этот переменный бонус.");

    public static bool TryGet(string token, string language, out string text)
    {
        if (string.IsNullOrEmpty(token)) { text = string.Empty; return false; }
        var key = token.StartsWith("$", StringComparison.Ordinal) ? token.Substring(1) : token;
        if (!Entries.TryGetValue(key, out var entry)) { text = string.Empty; return false; }
        text = string.Equals(language, "Russian", StringComparison.Ordinal) ? entry.Russian : entry.English;
        return true;
    }
}
